script:
(function () {
  'use strict';
  // Affordable rent from gross income and debts, plus a landlord income check.
  //   Monthly gross income I (annual / 12). Housing budget H = min(rent share * I,
  //   total share * I - monthly debts). Affordable rent = max(0, H - utilities paid separately).
  //   Landlord check: income needed = multiple * rent per month (3x is common; 40x the monthly rent
  //   per year is 3.33x).
  // Verified in Node (scratchpad tests/w3re): $80,000 a year, no debts, 30% -> $2,000.00/mo
  //   ($24,000 a year); $400/mo of debts with a 36% limit -> min($2,000, $2,000) = $2,000; $1,000 of
  //   debts -> $1,400 (debt limit binds); $150 utilities -> $1,850; $6,000 a month entered monthly
  //   equals $72,000 a year; a $2,500 rent needs $7,500/mo ($90,000 a year) at 3x and $100,000 a year
  //   at 40x; debts above the total limit -> $0; no NaN/Infinity on blank or bad input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var SHARES = [20, 25, 30, 35, 40];

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pct(x) { return (x * 100).toFixed(1) + '%'; }

  function clearResults() {
    ['rnRent', 'rnRentYear', 'rnShare', 'rnLeft', 'rnRentCap', 'rnDebtCap', 'rnTargetShare', 'rnTargetIncome', 'rnTargetVerdict']
      .forEach(function (id) { setText(id, '–'); });
    setText('rnBinding', '–');
    el('rnTable').innerHTML = '';
  }

  function update() {
    var income = read('rnIncome'), unit = el('rnIncomeUnit').value, debts = read('rnDebts', true),
        rentPct = read('rnRentPct'), totalPct = read('rnTotalPct'), utilities = read('rnUtilities', true),
        target = read('rnTarget', true), multiple = parseFloat(el('rnMultiple').value);
    var msg = '';
    if (isNaN(income) || income <= 0) msg = 'Enter your gross (pre-tax) income, greater than $0.';
    else if (isNaN(debts) || debts < 0 || isNaN(utilities) || utilities < 0) msg = 'Debts and utilities cannot be negative.';
    else if (isNaN(rentPct) || rentPct <= 0 || rentPct > 100) msg = 'Enter a rent share of income between 1% and 100%.';
    else if (isNaN(totalPct) || totalPct <= 0 || totalPct > 100) msg = 'Enter a limit for rent plus debts between 1% and 100%.';
    else if (isNaN(target) || target < 0) msg = 'The rent you are considering cannot be negative.';
    var error = el('rnError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var mi = unit === 'year' ? income / 12 : income;
    var rentCap = rentPct / 100 * mi, debtCap = totalPct / 100 * mi - debts;
    var budget = Math.min(rentCap, debtCap);
    var rent = Math.max(0, budget - utilities);

    setText('rnRent', money0.format(rent));
    setText('rnRentYear', money0.format(rent * 12));
    setText('rnShare', pct(rent / mi));
    setText('rnLeft', money.format(mi - rent - utilities - debts));
    setText('rnRentCap', money.format(rentCap));
    setText('rnDebtCap', money.format(Math.max(0, debtCap)));

    var note;
    if (debtCap <= 0) note = 'Your monthly debts already use the whole ' + totalPct + '% limit for rent plus debts, so these rules leave nothing for rent. Paying down debt or raising the limit changes this.';
    else if (rentCap <= debtCap) note = 'The ' + rentPct + '% rent rule sets your budget. Your debts are low enough not to matter.';
    else note = 'Your debts set the budget: rent plus ' + money0.format(debts) + ' of monthly debts can use ' + totalPct + '% of income. Each $100 of monthly debt you pay off frees $100 for rent, up to the ' + rentPct + '% rule.';
    if (utilities > 0 && budget > 0) note += ' ' + money0.format(utilities) + ' a month of separate utilities comes out of the budget first.';
    setText('rnBinding', note);

    if (target > 0) {
      var needMonthly = target * multiple;
      setText('rnTargetShare', pct(target / mi));
      setText('rnTargetIncome', money0.format(needMonthly) + ' a month (' + money0.format(needMonthly * 12) + ' a year)');
      setText('rnTargetVerdict', mi >= needMonthly - 0.005
        ? (target + utilities <= budget + 0.005 ? 'Meets the landlord rule and fits your budget' : 'Meets the landlord rule but is over your budget')
        : 'Below the landlord rule by ' + money0.format(needMonthly - mi) + ' a month');
    } else {
      ['rnTargetShare', 'rnTargetIncome', 'rnTargetVerdict'].forEach(function (id) { setText(id, '–'); });
    }

    el('rnTable').innerHTML = SHARES.map(function (s) {
      var r = s / 100 * mi, total = (r + debts) / mi;
      return '<tr><td>' + s + '%</td><td>' + money0.format(r) + '</td><td>' + money0.format(r * 12) + '</td><td>' + pct(total) +
        '</td><td>' + money0.format(mi - r - utilities - debts) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rnForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
